parameters.scriptCode:
let item = {};
try { if ($json && typeof $json === 'object') item = $json; } catch (e) {}
try {
  if (!item.task_url && typeof $input !== 'undefined' && $input && typeof $input.all === 'function') {
    const all = $input.all();
    if (all && all.length) item = all[0].json;
  }
} catch (e) {}

const platform = String(item.platform || '');
const runId = item.run_id;
const taskRef = item.task_ref;
const contentUrlRaw = String(item.task_url || '');
const adminUrl = String(item.target_url || '');
const adminToken = String(item.admin_token || '');
const accountEmail = String(item.account_email || '');
const adminUserCookie = encodeURIComponent(JSON.stringify({ name: 'Rama', role_id: 3, email: accountEmail }));
const raw = String(item.cookies_json || '').trim();
const BASE = 'https://admin.sistem-partisipasi.jovasoftware.id/';
const normalizeInstagramUrl = function (u) {
  const s = String(u || '');
  if (s.indexOf('instagram.com') === -1) return s;
  const keys = ['/reel/', '/reels/', '/p/'];
  let id = '';
  for (let i = 0; i < keys.length && !id; i++) {
    const p = s.indexOf(keys[i]);
    if (p === -1) continue;
    let rest = s.slice(p + keys[i].length);
    const q1 = rest.indexOf('?');
    if (q1 !== -1) rest = rest.slice(0, q1);
    const q2 = rest.indexOf('/');
    if (q2 !== -1) rest = rest.slice(0, q2);
    id = rest;
  }
  if (!id) return s;
  return 'https://www.instagram.com/p/' + id + '/';
};
const contentUrl = platform === 'Instagram' ? normalizeInstagramUrl(contentUrlRaw) : contentUrlRaw;
const proofFile = 'partisipasi-' + String(taskRef || 'task') + '-' + (platform || 'unknown') + '.jpg';
const base = { platform: platform, run_id: runId, task_ref: taskRef, content_url: contentUrl, target_url: adminUrl, proof_file_name: proofFile };

const stop = function (status, message) {
  return [{ json: Object.assign({}, base, { status: status, action_status: 'skipped', interaction_detail: message, screenshot_captured: 'no', submit_attempted: 'no', submit_status: 'skipped', submit_detail: message, last_error: message }) }];
};

if (!raw) return stop('no_session', 'cookies_json kosong untuk platform ini di tabel platform_sessions');
if (!contentUrl) return stop('no_target_url', 'task_url dan target_url kosong');
if (contentUrl.indexOf('sistem-partisipasi.jovasoftware.id/my-task') !== -1) return stop('admin_url_only', 'yang tersedia hanya URL halaman admin, bukan link kontennya');

let parsed;
try { parsed = JSON.parse(raw); } catch (e) { return stop('bad_json', String((e && e.message) || e)); }
const list = Array.isArray(parsed) ? parsed : (parsed && parsed.cookies ? parsed.cookies : []);

const mapSameSite = function (v) {
  const s = String(v || '').toLowerCase();
  if (s === 'no_restriction' || s === 'none') return 'None';
  if (s === 'strict') return 'Strict';
  if (s === 'lax' || s === 'unspecified') return 'Lax';
  return undefined;
};

const cookies = list.filter(function (c) { return c && c.name && c.value !== undefined; }).map(function (c) {
  const out = { name: c.name, value: String(c.value), path: c.path || '/' };
  if (c.domain) out.domain = c.domain;
  const ss = mapSameSite(c.sameSite);
  if (ss) out.sameSite = ss;
  if (typeof c.httpOnly === 'boolean') out.httpOnly = c.httpOnly;
  if (typeof c.secure === 'boolean') out.secure = c.secure;
  if (!c.session && c.expirationDate) out.expires = Math.floor(c.expirationDate);
  return out;
});
if (!cookies.length) return stop('no_cookies', 'tidak ada cookie yang bisa dibaca dari cookies_json');

const sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
const setCookieFn = ($browser && typeof $browser.setCookie === 'function') ? $browser.setCookie.bind($browser) : $page.setCookie.bind($page);
await setCookieFn(...cookies);

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36';
try { await $page.setUserAgent(UA); } catch (e) {}
try { await $page.setViewport({ width: 1366, height: 900, deviceScaleFactor: 1 }); } catch (e) {}
try { await $page.setExtraHTTPHeaders({ 'accept-language': 'en-US,en;q=0.9' }); } catch (e) {}

const sessionCookieNames = {
  Instagram: ['sessionid', 'ds_user_id'],
  TikTok: ['sessionid', 'sid_tt'],
  YouTube: ['SID', 'SAPISID', 'LOGIN_INFO']
};
const expected = sessionCookieNames[platform] || ['sessionid'];

try {
  await $page.goto(contentUrl, { waitUntil: 'domcontentloaded', timeout: 60000 });
} catch (e) {
  return stop('navigation_failed', String((e && e.message) || e));
}
await sleep(4000);

const readPage = async function () {
  return await $page.evaluate(function () {
    const body = document.body && document.body.innerText ? document.body.innerText : '';
    return { url: location.href, title: document.title, text: body.slice(0, 300) };
  });
};

const liveCookies = ($browser && typeof $browser.cookies === 'function') ? await $browser.cookies() : await $page.cookies();
const found = liveCookies.filter(function (c) { return expected.indexOf(c.name) !== -1; }).map(function (c) { return c.name; });
const before = await readPage();
const looksLoggedOut = before.url.indexOf('/login') !== -1 || before.url.indexOf('accounts.google.com') !== -1;

const pageFlags = async function () {
  return await $page.evaluate(function () {
    const q = function (s) { return document.querySelector(s); };
    const loginInputs = document.querySelectorAll('input[type="password"], input[name="username"], input[placeholder*="phone"], input[placeholder*="email"]').length;
    return {
      url: String(location.href),
      title: String(document.title || ''),
      has_captcha: document.querySelectorAll('[id*=captcha],[class*=captcha],[data-testid*=captcha],#verify-ele,[class*=verify]').length > 0,
      has_login_input: loginInputs > 0 && !q('video'),
      has_video: !!q('video'),
      has_like_ui: !!q('[data-e2e="like-icon"]') || !!q('[data-e2e="unlike-icon"]') || !!q('svg[aria-label="Like"][height="24"]') || !!q('like-button-view-model button') || !!q('ytd-subscribe-button-renderer button')
    };
  });
};

const waitForVisible = async function (selectors, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const hit = await $page.evaluate(function (selectors) {
      const ok = function (el) {
        if (!el) return false;
        try { if (el.offsetParent === null) return false; } catch (e) { return false; }
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      for (let i = 0; i < selectors.length; i++) {
        const nodes = document.querySelectorAll(selectors[i]);
        for (let j = 0; j < nodes.length; j++) { if (ok(nodes[j])) return selectors[i]; }
      }
      return '';
    }, selectors);
    if (hit) return hit;
    await sleep(1000);
  }
  return '';
};

const waitRender = async function () {
  const deadline = Date.now() + 25000;
  let last = {};
  while (Date.now() < deadline) {
    last = await $page.evaluate(function (platform) {
      const ok = function (el) {
        if (!el) return false;
        try { if (el.offsetParent === null) return false; } catch (e) { return false; }
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      const vids = document.querySelectorAll('video');
      let videoReady = false;
      for (let i = 0; i < vids.length; i++) { if (vids[i].readyState >= 2) { videoReady = true; break; } }
      let imgBad = false;
      const imgs = document.querySelectorAll('img');
      for (let i = 0; i < imgs.length && i < 10; i++) { if (imgs[i].naturalWidth === 0 && ok(imgs[i])) { imgBad = true; break; } }
      let likeUi = false;
      if (platform === 'TikTok') likeUi = ok(document.querySelector('[data-e2e="like-icon"]')) || ok(document.querySelector('[data-e2e="unlike-icon"]')) || ok(document.querySelector('[data-e2e="video-title"]'));
      if (platform === 'Instagram') likeUi = ok(document.querySelector('svg[aria-label="Unlike"][height="24"]')) || ok(document.querySelector('svg[aria-label="Like"][height="24"]')) || ok(document.querySelector('svg[aria-label="Suka"][height="24"]'));
      if (platform === 'YouTube') likeUi = ok(document.querySelector('like-button-view-model button')) || ok(document.querySelector('#segmented-like-button button')) || ok(document.querySelector('ytd-subscribe-button-renderer button'));
      return { video: videoReady, imgBad: imgBad, ad: !!document.querySelector('.ad-showing'), likeUi: likeUi };
    }, platform);
    if (!last.ad && (last.video || last.likeUi) && !last.imgBad) return last;
    await sleep(1000);
  }
  return last;
};

const clickDom = async function (selectors, textWords, doneWords) {
  return await $page.evaluate(function (selectors, textWords, doneWords) {
    const ok = function (el) {
      if (!el || el.disabled) return false;
      try { if (el.offsetParent === null) return false; } catch (e) { return false; }
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); };
    const fire = function (el) {
      try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
      el.click();
      try { el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true })); } catch (e) {}
    };
    if (doneWords && doneWords.length) {
      const all = Array.prototype.slice.call(document.querySelectorAll('button, [role="button"], div[role="button"], a'));
      for (let i = 0; i < all.length; i++) {
        const t = norm(all[i].innerText || all[i].textContent);
        for (let d = 0; d < doneWords.length; d++) { if (t === doneWords[d] && ok(all[i])) return { clicked: false, matched: 'already:' + t }; }
      }
    }
    for (let i = 0; i < selectors.length; i++) {
      const nodes = document.querySelectorAll(selectors[i]);
      for (let j = 0; j < nodes.length; j++) { if (ok(nodes[j])) { fire(nodes[j]); return { clicked: true, matched: selectors[i] }; } }
    }
    if (textWords && textWords.length) {
      const all = Array.prototype.slice.call(document.querySelectorAll('button, [role="button"], div[role="button"], a'));
      for (let t = 0; t < textWords.length; t++) {
        for (let i = 0; i < all.length; i++) {
          const label = norm(all[i].innerText || all[i].textContent);
          if (label === textWords[t] && ok(all[i])) { fire(all[i]); return { clicked: true, matched: 'text:' + label }; }
        }
      }
    }
    return { clicked: false, matched: 'not_found' };
  }, selectors, textWords || [], doneWords || []);
};

const mouseLikeYouTube = async function () {
  const sels = ['#segmented-like-button button', 'like-button-view-model button', 'ytd-segmented-like-dislike-button-renderer button'];
  const foundLike = await $page.evaluate(function (sels) {
    const ok = function (el) {
      if (!el || el.disabled) return false;
      try { if (el.offsetParent === null) return false; } catch (e) { return false; }
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    for (let i = 0; i < sels.length; i++) {
      const nodes = document.querySelectorAll(sels[i]);
      for (let j = 0; j < nodes.length; j++) {
        const el = nodes[j];
        if (!ok(el)) continue;
        if (el.getAttribute('aria-pressed') === 'true') return { state: 'already_liked', sel: sels[i] };
        const r = el.getBoundingClientRect();
        return { state: 'found', sel: sels[i], x: r.left + r.width / 2, y: r.top + r.height / 2 };
      }
    }
    return { state: 'not_found' };
  }, sels);
  if (foundLike.state === 'already_liked') return { clicked: false, matched: 'already_liked' };
  if (foundLike.state !== 'found') return { clicked: false, matched: 'not_found' };
  try {
    await $page.mouse.click(foundLike.x, foundLike.y);
  } catch (e) {
    return { clicked: false, matched: 'mouse_failed' };
  }
  await sleep(2500);
  const verdict = await $page.evaluate(function (sels) {
    const ok = function (el) {
      if (!el) return false;
      try { if (el.offsetParent === null) return false; } catch (e) { return false; }
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    for (let i = 0; i < sels.length; i++) {
      const nodes = document.querySelectorAll(sels[i]);
      for (let j = 0; j < nodes.length; j++) { if (ok(nodes[j]) && nodes[j].getAttribute('aria-pressed') === 'true') return 'liked'; }
    }
    return 'unverified';
  }, sels);
  return { clicked: true, matched: foundLike.sel + '|' + verdict };
};

const interactYouTube = async function (results) {
  const isShorts = String(contentUrl).indexOf('/shorts/') !== -1;
  results.push({ key: 'page', clicked: true, matched: JSON.stringify(await pageFlags()) });
  for (let i = 0; i < 12; i++) {
    const ad = await $page.evaluate(function () {
      const ok = function (el) {
        if (!el) return false;
        try { if (el.offsetParent === null) return false; } catch (e) { return false; }
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      const sels = ['.ytp-skip-ad-button', '.ytp-ad-skip-button-modern', 'button[class*="ytp-ad-skip"]'];
      for (let i = 0; i < sels.length; i++) {
        const nodes = document.querySelectorAll(sels[i]);
        for (let j = 0; j < nodes.length; j++) { if (ok(nodes[j])) { nodes[j].click(); return 'skipped'; } }
      }
      return document.querySelector('.ad-showing') ? 'playing' : 'none';
    });
    if (ad === 'none') break;
    await sleep(1000);
  }
  if (!isShorts) {
    const seek = await $page.evaluate(function () {
      const v = document.querySelector('video');
      if (!v) return false;
      try { v.muted = true; } catch (e) {}
      try { const p = v.play(); if (p && p.catch) p.catch(function () {}); } catch (e) {}
      if (v.duration && isFinite(v.duration) && v.duration > 3) { try { v.currentTime = v.duration - 1; } catch (e) {} return true; }
      return false;
    });
    results.push({ key: 'play', clicked: seek, matched: 'video' });
    await sleep(3000);
  }
  results.push(Object.assign({ key: 'subscribe' }, await clickDom(['ytd-subscribe-button-renderer button', '#subscribe-button button'], ['subscribe', 'berlangganan'], ['subscribed', 'berlangganan'])));
  results.push(Object.assign({ key: 'like' }, await mouseLikeYouTube()));
};

const interactInstagram = async function (results) {
  await waitForVisible(['svg[aria-label="Like"][height="24"]', 'svg[aria-label="Suka"][height="24"]', 'svg[aria-label="Unlike"][height="24"]', 'article video', 'article'], 15000);
  results.push(Object.assign({ key: 'follow' }, await clickDom([], ['follow', 'ikuti'], ['following', 'mengikuti', 'requested', 'diminta'])));
  results.push(Object.assign({ key: 'like' }, await $page.evaluate(function () {
    const ok = function (el) {
      if (!el) return false;
      try { if (el.offsetParent === null) return false; } catch (e) { return false; }
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    const unlikes = document.querySelectorAll('svg[aria-label="Unlike"][height="24"], svg[aria-label="Tidak Suka"][height="24"]');
    for (let i = 0; i < unlikes.length; i++) { if (ok(unlikes[i])) return { clicked: false, matched: 'already_liked' }; }
    const sections = Array.prototype.slice.call(document.querySelectorAll('section'));
    for (let i = 0; i < sections.length; i++) {
      const s = sections[i];
      const like = s.querySelector('svg[aria-label="Like"][height="24"], svg[aria-label="Suka"][height="24"]');
      const comment = s.querySelector('svg[aria-label="Comment"][height="24"], svg[aria-label="Komentar"][height="24"]');
      const share = s.querySelector('svg[aria-label="Share"][height="24"], svg[aria-label="Bagikan"][height="24"]');
      if (!like || !comment || !share || !ok(like)) continue;
      const btn = like.closest('div[role="button"], button') || like;
      try { btn.scrollIntoView({ block: 'center' }); } catch (e) {}
      btn.click();
      return { clicked: true, matched: 'post_action_like' };
    }
    return { clicked: false, matched: 'not_found' };
  })));
  await sleep(2500);
  results.push({ key: 'like_verify', clicked: true, matched: String(await $page.evaluate(function () { return !!document.querySelector('svg[aria-label="Unlike"][height="24"]'); })) });
};

const interactTikTok = async function (results) {
  await waitForVisible(['[data-e2e="video-title"]', '[data-e2e="like-icon"]', '[data-e2e="unlike-icon"]', 'video'], 20000);
  const followState = await $page.evaluate(function () {
    const ok = function (el) {
      if (!el) return false;
      try { if (el.offsetParent === null) return false; } catch (e) { return false; }
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    };
    return ok(document.querySelector('[data-e2e="unfollow-button"]')) ? 'already_following' : '';
  });
  if (followState) results.push({ key: 'follow', clicked: false, matched: 'already_following' });
  else results.push(Object.assign({ key: 'follow' }, await clickDom(['[data-e2e="feed-follow"]', '[data-e2e="follow-button"]', '[data-e2e="browse-follow"]'], ['follow', 'ikuti'], ['following', 'mengikuti'])));
  const tiktokLikeOnce = async function () {
    return await $page.evaluate(function () {
      const ok = function (el) {
        if (!el) return false;
        try { if (el.offsetParent === null) return false; } catch (e) { return false; }
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      if (ok(document.querySelector('[data-e2e="unlike-icon"]'))) return { clicked: false, matched: 'already_liked' };
      const like = document.querySelector('[data-e2e="like-icon"]');
      if (!ok(like)) return { clicked: false, matched: 'not_found' };
      like.click();
      try { like.dispatchEvent(new MouseEvent('mouseup', { bubbles: true })); } catch (e) {}
      return { clicked: true, matched: 'like-icon' };
    });
  };
  const tiktokLiked = async function () {
    return await $page.evaluate(function () { return !!document.querySelector('[data-e2e="unlike-icon"]'); });
  };
  let tiktokVerdict = { clicked: false, matched: 'not_attempted' };
  for (let attempt = 0; attempt < 3; attempt++) {
    const tried = await tiktokLikeOnce();
    if (tried.matched === 'already_liked' || !tried.clicked) { tiktokVerdict = tried; break; }
    await sleep(2500);
    if (await tiktokLiked()) { tiktokVerdict = { clicked: true, matched: 'like-icon|liked' }; break; }
    tiktokVerdict = { clicked: true, matched: 'like-icon|unverified,attempt' + String(attempt + 1) };
    await sleep(2500);
  }
  results.push(Object.assign({ key: 'like' }, tiktokVerdict));
  results.push({ key: 'like_verify', clicked: true, matched: String(await tiktokLiked()) });
};

const results = [];
if (found.length && !looksLoggedOut) {
  try {
    if (platform === 'YouTube') {
      await interactYouTube(results);
    } else if (platform === 'Instagram') {
      await interactInstagram(results);
    } else if (platform === 'TikTok') {
      await interactTikTok(results);
    } else {
      results.push({ key: 'platform_unknown', clicked: false, matched: platform });
    }
  } catch (e) {
    results.push({ key: 'interaction_error', clicked: false, matched: String((e && e.message) || e) });
  }
} else if (!found.length) {
  results.push({ key: 'no_session', clicked: false, matched: 'session cookie tidak ditemukan untuk platform ini' });
} else {
  results.push({ key: 'login_required', clicked: false, matched: before.url });
}
await waitRender();
await sleep(2000);

let shot = '';
try {
  shot = await $page.screenshot({ type: 'jpeg', quality: 70, fullPage: false, encoding: 'base64' });
} catch (e) {
  results.push({ key: 'screenshot_error', clicked: false, matched: String((e && e.message) || e) });
}

// ---- submit the task on its admin page: the page itself uploads the image and handles the expired-task modal ----
const submit = { attempted: 'no', status: 'skipped', detail: '', error: '', file: '', button: '', modal: '', page_url: '', page_text: '' };
const probe = {};

const waitSubmitOutcome = async function () {
  const deadline = Date.now() + 25000;
  let last = {};
  while (Date.now() < deadline) {
    last = await $page.evaluate(function () {
      const t = String(document.body && document.body.innerText ? document.body.innerText : '').toLowerCase();
      const modal = document.getElementById('upload_reason_modal');
      let modalOpen = false;
      if (modal) {
        try {
          const s = window.getComputedStyle(modal);
          const r = modal.getBoundingClientRect();
          modalOpen = s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0;
        } catch (e) {}
      }
      return {
        url: String(location.href),
        fileInputs: document.querySelectorAll('input[type="file"]').length,
        modalOpen: modalOpen,
        submittedText: t.indexOf('submitted your task') !== -1 || t.indexOf('thank you for submitting') !== -1 || t.indexOf('berhasil') !== -1 || t.indexOf('sukses') !== -1,
        errorText: t.indexOf('gagal') !== -1 || t.indexOf('wajib diisi') !== -1 || t.indexOf('harus diisi') !== -1 || t.indexOf('tidak valid') !== -1
      };
    });
    if (last.submittedText || last.errorText || last.modalOpen) return last;
    if (String(last.url || '').indexOf('/my-task/') === -1) return last;
    await sleep(1500);
  }
  return last;
};

const handleExpiredModal = async function () {
  const out = { present: false, filled: false, submitted: false };
  const modalOpen = async function () {
    return await $page.evaluate(function () {
      const m = document.getElementById('upload_reason_modal');
      if (!m) return false;
      try {
        const s = window.getComputedStyle(m);
        const r = m.getBoundingClientRect();
        return s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0;
      } catch (e) { return false; }
    });
  };
  out.present = await modalOpen();
  if (!out.present) return out;
  out.filled = await $page.evaluate(function () {
    const m = document.getElementById('upload_reason_modal');
    if (!m) return false;
    const f = m.querySelector('textarea, input[type="text"], input:not([type])');
    if (!f) return false;
    const proto = f.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
    const d = Object.getOwnPropertyDescriptor(proto, 'value');
    if (d && d.set) { d.set.call(f, '-'); } else { f.value = '-'; }
    f.dispatchEvent(new Event('input', { bubbles: true }));
    f.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  });
  await sleep(800);
  out.submitted = await $page.evaluate(function () {
    const m = document.getElementById('upload_reason_modal');
    if (!m) return false;
    const nodes = Array.prototype.slice.call(m.querySelectorAll('button, input[type="submit"], [role="button"]'));
    for (let i = 0; i < nodes.length; i++) {
      const label = String(nodes[i].innerText || nodes[i].textContent || nodes[i].value || '').toLowerCase().trim();
      if (label === 'submit' || label === 'kirim' || label === 'simpan' || label === 'ok' || label === 'oke') { nodes[i].click(); return true; }
    }
    return false;
  });
  await sleep(4000);
  return out;
};

const clickSubmitOutsideModal = async function () {
  const attemptOnce = async function () {
    return await $page.evaluate(function () {
      const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); };
      const modal = document.getElementById('upload_reason_modal');
      const wanted = ['submit', 'submit task', 'submit proof', 'kirim']; 
      const nodes = Array.prototype.slice.call(document.querySelectorAll('button, input[type="submit"], [role="button"]'));
      for (let pass = 0; pass < 2; pass++) {
        for (let t = 0; t < wanted.length; t++) {
          for (let i = 0; i < nodes.length; i++) {
            const el = nodes[i];
            if (modal && modal.contains(el)) continue;
            const rect = el.getBoundingClientRect();
            if (!(rect.width > 0 && rect.height > 0)) continue;
            const cst = window.getComputedStyle(el);
            if (cst.display === 'none' || cst.visibility === 'hidden') continue;
            const label = norm(el.innerText || el.textContent || el.value);
            if (!label) continue;
            const hit = pass === 0 ? (label === wanted[t]) : (label.indexOf(wanted[t]) === 0);
            if (!hit) continue;
            if (el.disabled) return { clicked: false, disabled: true, label: label };
            el.click();
            return { clicked: true, disabled: false, label: label };
          }
        }
      }
      return { clicked: false, disabled: false, label: '' };
    });
  };
  let last = { clicked: false, disabled: false, label: '' };
  for (let i = 0; i < 15; i++) {
    last = await attemptOnce();
    if (last.clicked) return last;
    if (last.disabled) { await sleep(1500); continue; }
    return last;
  }
  return last;
};

const setFileInput = async function (b64, fileName, mime) {
  return await $page.evaluate(function (b64, fileName, mime) {
    const inputs = Array.prototype.slice.call(document.querySelectorAll('input[type="file"]'));
    if (!inputs.length) return { ok: false, reason: 'no_file_input' };
    let target = null;
    for (let i = 0; i < inputs.length; i++) { if (!inputs[i].disabled) { target = inputs[i]; break; } }
    if (!target) target = inputs[0];
    try {
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let j = 0; j < bin.length; j++) bytes[j] = bin.charCodeAt(j);
      const file = new File([bytes], fileName, { type: mime });
      const dt = new DataTransfer();
      dt.items.add(file);
      target.files = dt.files;
    } catch (e) {
      return { ok: false, reason: 'assign_failed:' + String((e && e.message) || e) };
    }
    try { target.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
    try { target.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
    return { ok: true, name: String(target.name || target.id || ''), count: target.files ? target.files.length : 0 };
  }, b64, fileName, mime);
};

const probePage = async function () {
  return await $page.evaluate(function () {
    const cut = function (s, n) { const t = String(s || '').replace(/ +/g, ' ').trim(); return t.length > n ? t.slice(0, n) : t; };
    const vis = function (el) {
      if (!el) return false;
      const r = el.getBoundingClientRect();
      if (!(r.width > 0 && r.height > 0)) return false;
      const st = window.getComputedStyle(el);
      return st.display !== 'none' && st.visibility !== 'hidden';
    };
    const out = { url: String(location.href), buttons: [], inputs: [], file_inputs: [], dialogs: [], upload_area: '' };
    const files = Array.prototype.slice.call(document.querySelectorAll('input[type="file"]'));
    for (let i = 0; i < files.length; i++) {
      out.file_inputs.push({ name: cut(files[i].getAttribute('name') || '', 30), id: cut(files[i].id || '', 30), accept: cut(files[i].accept || '', 30), visible: vis(files[i]), disabled: !!files[i].disabled });
    }
    const els = Array.prototype.slice.call(document.querySelectorAll('button, [role="button"], a, label, input, textarea, select, [role="dialog"], dialog, form'));
    for (let i = 0; i < els.length && (out.buttons.length + out.inputs.length) < 120; i++) {
      const el = els[i];
      const tag = String(el.tagName || '').toLowerCase();
      const cls = (el.className && typeof el.className === 'string') ? el.className : '';
      const rec = { tag: tag, type: cut(el.getAttribute('type') || '', 20), name: cut(el.getAttribute('name') || '', 30), id: cut(el.id || '', 30), text: cut(el.innerText || el.textContent || el.value || el.getAttribute('aria-label') || '', 40), visible: vis(el), disabled: !!el.disabled };
      if (tag === 'input' || tag === 'textarea' || tag === 'select') {
        out.inputs.push(rec);
      } else {
        out.buttons.push(rec);
      }
      if (tag === 'form' || tag === 'dialog' || el.getAttribute('role') === 'dialog') out.dialogs.push(rec);
    }
    const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); };
    const cands = Array.prototype.slice.call(document.querySelectorAll('button, a, label, div, span, h2, h3, p'));
    for (let i = 0; i < cands.length; i++) {
      if (norm(cands[i].textContent) !== 'upload proof') continue;
      const parent = cands[i].parentElement;
      out.upload_area = cut(cands[i].outerHTML, 900) + ' ||PARENT|| ' + cut(parent ? parent.outerHTML : '', 1600);
      break;
    }
    return out;
  });
};

const clickUploadTrigger = async function () {
  return await $page.evaluate(function () {
    const norm = function (s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); };
    const vis = function (el) {
      if (!el) return false;
      const r = el.getBoundingClientRect();
      if (!(r.width > 0 && r.height > 0)) return false;
      const st = window.getComputedStyle(el);
      return st.display !== 'none' && st.visibility !== 'hidden';
    };
    const nodes = Array.prototype.slice.call(document.querySelectorAll('button, a, label, [role="button"], div, span'));
    for (let i = 0; i < nodes.length; i++) {
      const el = nodes[i];
      if (norm(el.innerText || el.textContent) !== 'upload proof') continue;
      if (!vis(el)) continue;
      const target = el.closest('button, a, label, [role="button"]') || el;
      target.click();
      return { clicked: true, tag: String(target.tagName || '').toLowerCase() };
    }
    const labels = Array.prototype.slice.call(document.querySelectorAll('label'));
    for (let i = 0; i < labels.length; i++) {
      if (!vis(labels[i])) continue;
      labels[i].click();
      return { clicked: true, tag: 'label' };
    }
    return { clicked: false };
  });
};

